import{_ as o,l,o as e,c as s,v as t,p as E,x as i,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"电子束邻近校正细节","description":"","frontmatter":{"title":"电子束邻近校正细节","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-pec-detail.md","filePath":"litho/mask-pec-detail.md","lastUpdated":1789023840000}'),h={name:"litho/mask-pec-detail.md"};function c(A,a,m,C,_,D){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="电子束邻近校正细节" tabindex="-1">电子束邻近校正细节 <a class="header-anchor" href="#电子束邻近校正细节" aria-label="Permalink to &quot;电子束邻近校正细节&quot;">​</a></h1><div class="epigraph"><p>双高斯核把前向与背向拆开；雾化是更平的第三层。细节错了，密度相关 CD 会在 PEC「已经打开」之后仍在走。</p><footer>—— 对照电子束 PEC 双高斯 / 雾化模型的通称；基础见写掩模邻近校正文献</footer></div><p><a href="/litho/mask-write-time">上一课</a>把写入小时钉成家族公式。缺口是剂量图本身：通称 PEC 课已经说了「调剂量不调多边形」，本课补核的阶次、校准与过校正。网格与炮数如何量化这张图，留给[下一课](/litho/write-grid-shot-count）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/ebeam-mask-pec">电子束 PEC</a> 给出短程、长程、雾化三层图像。细节是：短程（前向散射 + 束斑）决定边锐与小助条能否存在；长程（背散射）核宽随加速电压与衬底 Z 变；雾化（腔体二次电子）更接近全版底板。三层若用一个有效高斯去拟合，疏密交界会出现无法用一层 MPC 修掉的斜坡。</p><p>缺口是<strong>核与校准集</strong>，不是再定义一次 PEC。把「PEC on」当成 CDU 已合格，会漏掉：核半径用错时，校正把误差搬到另一种节距。</p><h3 id="过校正振荡" tabindex="-1">过校正振荡 <a class="header-anchor" href="#过校正振荡" aria-label="Permalink to &quot;过校正振荡&quot;">​</a></h3><p>反解剂量是病态的：短程核把高频放大。正则不足时，密区剂量被砍过头，下一轮密度图又反过来，CD 随迭代摆。这与晶圆 OPC 振荡同构。工程上限制剂量动态范围、平滑密度图、分短/长程分别收敛。</p><p><span class="marginnote">EUV 吸收体与 DUV 铬的背散射不同。换膜系等于重测核，不能只改 MPC 表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>双高斯（或三高斯）拟合曝光测试：孤立/密集线、倒比、大面积垫。雾化用全版或大窗曝光单独标定。写入时卷积密度图得到本底，再按阈值模型求每炮或每像素剂量。多束路径在栅格上做同一件事，只是 primitive 从炮换成像素。</p><p>与写入时间的耦合：PEC 动态范围大 → 平均剂量或遍数涨 → 日历涨。为了赶货而缩小 PEC 范围，等于把残差推给 mask CDU。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>入射电子在胶中损失能量（前向），一部分从铬/石英或 EUV 多层回来（背向）。背向电子在微米量级叠加本底，本底与周围开口率成正比。显影阈值切在「本地 + 本底」上，故同样数据宽度在密区更胖。PEC 求的是让有效能量对齐的入射剂量。加速电压升高，背向核往往变宽，长程项更重——这是写模参数，不是晶圆 NA。</p><p>版边缺邻居，长程卷积要 pad 或改边界条件，否则边框 CD 像「写出来的 flare」。这与 <a href="/litho/six-inch-reticle">6 寸有效区</a> 直接相关。</p>',15)),(e(),E(p,null,{default:i(()=>[d(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEN%5B%22%E5%BC%80%E5%8F%A3%E5%AF%86%E5%BA%A6%E5%9B%BE%22%5D%20--%3E%20FWD%5B%22%E7%9F%AD%E7%A8%8B%E6%A0%B8%22%5D%0A%20%20DEN%20--%3E%20BACK%5B%22%E8%83%8C%E6%95%A3%E5%B0%84%E6%A0%B8%22%5D%0A%20%20DEN%20--%3E%20FOG%5B%22%E9%9B%BE%E5%8C%96%E5%BA%95%E6%9D%BF%22%5D%0A%20%20FWD%20--%3E%20DOSE%5B%22%E5%8F%8D%E8%A7%A3%E5%89%82%E9%87%8F%22%5D%0A%20%20BACK%20--%3E%20DOSE%0A%20%20FOG%20--%3E%20DOSE%0A%20%20DOSE%20--%3E%20CD%5B%22%E6%8E%A9%E6%A8%A1%20CD-%E5%AF%86%E5%BA%A6%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不发明核的微米半径表，不写某厂软件名。不把化学放大胶的酸扩散与电子核写成同一个 σ。PEC 细节不替代掩模检验。</p><p>后课默认：剂量图按多层核来；下一课问这张图落在多细的地址栅上、VSB 要多少炮才能实现它。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEC 细节是短程 / 背向 / 雾化分核，不是一开开关。</li><li>过校正会振荡；动态范围与写入时间耦合。</li><li>版边要单独处理长程核；换吸收体要重测。</li><li>出处：电子束 PEC 双高斯与雾化校正通称；写掩模邻近文献。</li></ul>',5))])}const u=o(h,[["render",c]]);export{P as __pageData,u as default};
